  Dua("prayer", "نماز کے بعد تسبیحات", "Tasbih after prayer", "التسبيح بعد الصلاة", "سُبْحَانَ اللَّهِ (٣٣)، الْحَمْدُ لِلَّهِ (٣٣)، اللَّهُ أَكْبَرُ (٣٤)", "سبحان اللہ 33 بار، الحمد للہ 33 بار اور اللہ اکبر 34 بار (کل 100)۔ تسبیح کے صفحے پر گن سکتے ہیں۔", "Subhan Allah 33 times, Alhamdulillah 33 times and Allahu Akbar 34 times (total 100). You can count them in the Tasbeeh page.", "M", ""),
  Dua("prayer", "نماز کے بعد: ذکر و شکر کی توفیق", "After prayer: help in remembrance", "دعاء بعد الصلاة", "اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ", "اے اللہ! اپنے ذکر، شکر اور اچھی عبادت پر میری مدد فرما۔", "O Allah, help me to remember You, to thank You and to worship You in the best manner.", "DN", ""),
  Dua("prayer", "آیت الکرسی", "Ayat al-Kursi", "آية الكرسي", "اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ", "اللہ، اس کے سوا کوئی معبود نہیں، وہ زندہ ہے، سب کو تھامنے والا ہے۔ اسے نہ اونگھ آتی ہے نہ نیند۔ آسمانوں اور زمین میں جو کچھ ہے سب اسی کا ہے۔ کون ہے جو اس کی اجازت کے بغیر اس کے ہاں سفارش کرے؟ وہ جانتا ہے جو ان کے آگے ہے اور جو ان کے پیچھے ہے، اور وہ اس کے علم میں سے کسی چیز کا احاطہ نہیں کر سکتے مگر جتنا وہ چاہے۔ اس کی کرسی آسمانوں اور زمین کو گھیرے ہوئے ہے اور ان کی حفاظت اسے تھکاتی نہیں، اور وہ بلند و عظیم ہے۔", "Allah, there is no deity except Him, the Ever-Living, the Sustainer of all existence. Neither drowsiness nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass nothing of His knowledge except what He wills. His Throne extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.", "Q:2:255", ""),
  Dua("quran", "دنیا و آخرت کی بھلائی", "Good in this world and the next", "ربنا آتنا في الدنيا حسنة", "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", "اے ہمارے رب! ہمیں دنیا میں بھلائی دے اور آخرت میں بھلائی دے اور ہمیں آگ کے عذاب سے بچا۔", "Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.", "Q:2:201", ""),
  Dua("quran", "بھول چوک پر معافی", "Forgiveness for mistakes", "ربنا لا تؤاخذنا", "رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ", "اے ہمارے رب! اگر ہم بھول جائیں یا خطا کریں تو ہمیں نہ پکڑنا۔ اے ہمارے رب! ہم پر ویسا بوجھ نہ ڈال جیسا ہم سے پہلے لوگوں پر ڈالا۔ اے ہمارے رب! ہم پر وہ بوجھ نہ ڈال جس کی ہمیں طاقت نہیں۔ ہمیں معاف کر، ہمیں بخش دے اور ہم پر رحم کر۔ تو ہی ہمارا مددگار ہے، پس کافروں کے مقابلے میں ہماری مدد فرما۔", "Our Lord, do not impose blame upon us if we forget or make a mistake. Our Lord, do not lay on us a burden like that which You laid on those before us. Our Lord, do not burden us with what we have no ability to bear. Pardon us, forgive us and have mercy upon us. You are our protector, so give us victory over the disbelieving people.", "Q:2:286", ""),
  Dua("quran", "سینے کی کشادگی اور آسانی", "Ease and an open heart", "ربّ اشرح لي صدري", "رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي", "اے میرے رب! میرا سینہ کھول دے اور میرا کام آسان کر دے۔", "My Lord, expand for me my chest and ease for me my task.", "Q:20:25-26", ""),
  Dua("quran", "علم میں اضافہ", "Increase in knowledge", "ربّ زدني علما", "رَبِّ زِدْنِي عِلْمًا", "اے میرے رب! میرے علم میں اضافہ فرما۔", "My Lord, increase me in knowledge.", "Q:20:114", ""),
  Dua("quran", "توبہ کی دعا", "Dua of repentance", "ربنا ظلمنا أنفسنا", "رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ", "اے ہمارے رب! ہم نے اپنی جانوں پر ظلم کیا، اگر تو ہمیں نہ بخشے اور ہم پر رحم نہ کرے تو ہم ضرور نقصان اٹھانے والوں میں ہوں گے۔", "Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.", "Q:7:23", ""),
  Dua("quran", "اہل و عیال اور اولاد کے لیے", "For spouse and children", "ربنا هب لنا من أزواجنا", "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا", "اے ہمارے رب! ہمیں ہماری بیویوں اور اولاد کی طرف سے آنکھوں کی ٹھنڈک عطا فرما اور ہمیں پرہیزگاروں کا پیشوا بنا دے۔", "Our Lord, grant us from among our spouses and offspring comfort to our eyes and make us a leader for the righteous.", "Q:25:74", ""),
  Dua("quran", "والدین اور مومنوں کی مغفرت", "Forgiveness for parents and believers", "ربنا اغفر لي ولوالدي", "رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ", "اے ہمارے رب! مجھے، میرے والدین کو اور سب مومنوں کو حساب کے دن بخش دے۔", "Our Lord, forgive me and my parents and the believers on the Day when the account is established.", "Q:14:41", ""),
  Dua("quran", "والدین پر رحم کی دعا", "Mercy upon parents", "رب ارحمهما", "رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا", "اے میرے رب! ان دونوں پر رحم فرما جیسا انہوں نے بچپن میں مجھے پالا۔", "My Lord, have mercy upon them as they brought me up when I was small.", "Q:17:24", ""),
  Dua("quran", "دل کی ثابت قدمی", "Steadfast heart", "ربنا لا تزغ قلوبنا", "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً ۚ إِنَّكَ أَنْتَ الْوَهَّابُ", "اے ہمارے رب! ہدایت دینے کے بعد ہمارے دلوں کو ٹیڑھا نہ کر اور ہمیں اپنے پاس سے رحمت عطا فرما، بے شک تو ہی بہت عطا کرنے والا ہے۔", "Our Lord, let not our hearts deviate after You have guided us, and grant us from Yourself mercy. Indeed, You are the Bestower.", "Q:3:8", ""),
  Dua("quran", "دعائے یونس علیہ السلام", "Dua of Yunus (peace be upon him)", "دعاء يونس", "لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ", "تیرے سوا کوئی معبود نہیں، تو پاک ہے، بے شک میں ظالموں میں سے تھا۔", "There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers.", "Q:21:87", ""),
  Dua("hadith", "پریشانی اور غم سے پناہ", "Refuge from worry and grief", "الاستعاذة من الهم والحزن", "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ", "اے اللہ! میں فکر اور غم سے، عاجزی اور سستی سے، بخل اور بزدلی سے، قرض کے بوجھ سے اور لوگوں کے غلبے سے تیری پناہ مانگتا ہوں۔", "O Allah, I seek refuge in You from worry and grief, from weakness and laziness, from miserliness and cowardice, from the burden of debt and from being overpowered by men.", "B", ""),
  Dua("hadith", "معافی کی دعا", "Dua for pardon", "دعاء العفو", "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "اے اللہ! تو بہت معاف کرنے والا ہے، معافی کو پسند کرتا ہے، پس مجھے معاف فرما دے۔", "O Allah, You are Most Forgiving and love to forgive, so forgive me.", "TI", ""),
  Dua("hadith", "دل کو دین پر ثابت رکھنا", "Steadfastness in faith", "يا مقلب القلوب", "يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ", "اے دلوں کو پھیرنے والے! میرے دل کو اپنے دین پر ثابت رکھ۔", "O Turner of the hearts, keep my heart firm upon Your religion.", "T", ""),
  Dua("hadith", "ہدایت، تقویٰ، پاکدامنی اور بے نیازی", "Guidance, piety, chastity, contentment", "اللهم إني أسألك الهدى", "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى", "اے اللہ! میں تجھ سے ہدایت، تقویٰ، پاکدامنی اور (لوگوں سے) بے نیازی مانگتا ہوں۔", "O Allah, I ask You for guidance, piety, chastity and self-sufficiency.", "M", ""),
  Dua("daily", "چھینک آنے پر", "When sneezing", "دعاء العطاس", "الْحَمْدُ لِلَّهِ — جواب: يَرْحَمُكَ اللَّهُ — اس کا جواب: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ", "چھینکنے والا کہے \"الحمد للہ\"، سننے والا کہے \"یرحمک اللہ\" (اللہ تم پر رحم کرے)، پھر چھینکنے والا کہے \"یہدیکم اللہ ویصلح بالکم\" (اللہ تمہیں ہدایت دے اور تمہارا حال درست کرے)۔", "The sneezer says \"Alhamdulillah\"; the listener says \"Yarhamuk Allah\" (may Allah have mercy on you); then the sneezer says \"Yahdikum Allah wa yuslih balakum\" (may Allah guide you and set right your affairs).", "B", ""),
  Dua("daily", "بیمار کی عیادت پر", "Visiting the sick", "دعاء عيادة المريض", "لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ", "کوئی حرج نہیں، ان شاء اللہ یہ (بیماری) گناہوں سے پاکی کا ذریعہ ہے۔", "No harm, it is a purification, if Allah wills.", "B", ""),
  Dua("daily", "بارش کے وقت", "When it rains", "دعاء المطر", "اللَّهُمَّ صَيِّبًا نَافِعًا", "اے اللہ! نفع بخش بارش برسا۔", "O Allah, make it a beneficial rain.", "B", ""),
  Dua("daily", "نکاح کی مبارکباد", "Congratulating the newly married", "دعاء للمتزوج", "بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ", "اللہ تمہیں برکت دے، تم پر برکت نازل کرے اور تم دونوں کو خیر میں جمع رکھے۔", "May Allah bless you, shower blessings upon you and unite you both in goodness.", "DT", ""),
];